// Pointer Subtraction: Result is std::ptrdiff_t
int data[10];
int* p1 = data + 2;
int* p2 = data + 7;

// Pointers must belong to the same array or one past the end.

// Result calculation:
// (address(p2) - address(p1)) / sizeof(int)

// std::ptrdiff_t holds the difference in element count (signed)
std::ptrdiff_t diff = p2 - p1; // 5

// Negative difference
std::ptrdiff_t neg_diff = p1 - p2; // -5

// Result type required for safe array indexing
size_t length = p2 - data; // 7 (Warning: ptrdiff_t vs size_t)
